"""Temporal candidate controller with safety gating, target hysteresis, and bounded progress memory."""

# EVOLVE-BLOCK-START
MOTION_ACTIONS = ("FORWARD", "VEER_LEFT", "VEER_RIGHT")


def safety_contract(observation, memory):
    """Stop whenever safety evidence is weak or collision risk is high."""
    if (
        float(observation.get("safety_confidence", 0.0)) < 0.60
        or float(observation.get("closing_risk", 1.0)) >= 0.75
    ):
        memory["state"] = "STOPPED"
        memory["last_action"] = "STOP"
        return "STOP", 0.99
    return None


def tracking_contract(observation, memory):
    """Hold or scan conservatively during target loss, with a stable scan direction."""
    visible = bool(observation.get("target_visible", False))
    reliable = (
        visible
        and float(observation.get("target_confidence", 0.0)) >= 0.55
        and float(observation.get("target_identity_confidence", 0.0)) >= 0.60
    )
    if reliable:
        memory["lost_steps"] = 0
        return None

    lost_steps = int(observation.get("lost_steps", 0))
    memory["lost_steps"] = max(lost_steps, int(memory.get("lost_steps", 0)))
    if memory.get("state") in {"LOCKED", "APPROACH", "REACQUIRE"} and lost_steps <= 1:
        memory["state"] = "REACQUIRE"
        memory["last_action"] = "STOP"
        return "STOP", 0.92

    bearing = float(observation.get("target_bearing", 0.0))
    if abs(bearing) > 8.0:
        direction = "VEER_LEFT" if bearing < 0.0 else "VEER_RIGHT"
    else:
        direction = memory.get("scan_direction", "VEER_LEFT")
    memory["scan_direction"] = direction
    memory["state"] = "SEARCH"
    memory["last_action"] = direction
    return direction, 0.75


def propose_moves(observation, memory):
    """Rank observable corridor moves by bearing alignment and forward continuity."""
    bearing = float(observation.get("target_bearing", 0.0))
    candidates = []
    previous = memory.get("last_action")

    if abs(bearing) <= 12.0 and observation.get("corridor_center", False):
        candidates.append("FORWARD")
    if bearing < -12.0 and observation.get("corridor_left", False):
        candidates.append("VEER_LEFT")
    if bearing > 12.0 and observation.get("corridor_right", False):
        candidates.append("VEER_RIGHT")

    if previous in MOTION_ACTIONS and previous not in candidates:
        if (
            (previous == "FORWARD" and observation.get("corridor_center", False))
            or (previous == "VEER_LEFT" and observation.get("corridor_left", False))
            or (previous == "VEER_RIGHT" and observation.get("corridor_right", False))
        ):
            candidates.append(previous)

    if observation.get("corridor_center", False):
        candidates.append("FORWARD")
    if observation.get("corridor_left", False):
        candidates.append("VEER_LEFT")
    if observation.get("corridor_right", False):
        candidates.append("VEER_RIGHT")
    return list(dict.fromkeys(candidates))


def progress_contract(observation, memory, candidates):
    """Use short hysteresis to avoid needless target-switching and instruction flips."""
    if not candidates:
        return None

    previous = memory.get("last_action")
    if previous in candidates and int(memory.get("hold_steps", 0)) < 2:
        memory["hold_steps"] = int(memory.get("hold_steps", 0)) + 1
        return previous

    bearing = float(observation.get("target_bearing", 0.0))
    preferred = "FORWARD"
    if bearing < -12.0:
        preferred = "VEER_LEFT"
    elif bearing > 12.0:
        preferred = "VEER_RIGHT"

    action = preferred if preferred in candidates else candidates[0]
    memory["hold_steps"] = 0 if action != previous else int(memory.get("hold_steps", 0)) + 1
    return action


def termination_contract(observation, memory):
    """Return a high-confidence stop when no safe corridor proposal is available."""
    memory["state"] = "STOPPED"
    memory["last_action"] = "STOP"
    return "STOP", 0.98


def decide(observation, memory):
    """Compose safety, tracking, arrival, progress, and termination into three outputs."""
    memory = dict(memory or {})

    safety = safety_contract(observation, memory)
    if safety is not None:
        return safety[0], safety[1], memory

    tracking = tracking_contract(observation, memory)
    if tracking is not None:
        return tracking[0], tracking[1], memory

    memory["state"] = "LOCKED"
    distance = observation.get("target_distance_class")
    heading_error = abs(float(observation.get("heading_error", 180.0)))
    identity_confidence = float(observation.get("target_identity_confidence", 0.0))

    if distance == "near" and heading_error <= 15.0 and identity_confidence >= 0.80:
        memory["state"] = "ARRIVED"
        memory["last_action"] = "ARRIVED"
        return "ARRIVED", 0.96, memory

    if distance == "near":
        bearing = float(observation.get("target_bearing", 0.0))
        candidates = [
            "VEER_LEFT" if bearing < 0.0 else "VEER_RIGHT"
        ]
        candidates = [
            action for action in candidates
            if (
                action == "VEER_LEFT" and observation.get("corridor_left", False)
            ) or (
                action == "VEER_RIGHT" and observation.get("corridor_right", False)
            )
        ]
    else:
        candidates = propose_moves(observation, memory)

    action = progress_contract(observation, memory, candidates)
    if action is None:
        fallback = termination_contract(observation, memory)
        return fallback[0], fallback[1], memory

    memory["state"] = "APPROACH"
    memory["last_action"] = action
    return action, 0.90, memory


# EVOLVE-BLOCK-END
